import queue

import pytest


def accepted(cap: int, xs: list[int]) -> int:
    """Count how many elements of xs a bounded queue accepts before it is full.

    Creates a queue.Queue of capacity cap and tries to put each element of xs
    in order without blocking (put_nowait). Stops at the first element that
    is rejected because the queue is full and returns the number accepted
    so far. Nothing is ever taken from the queue.

    A capacity of zero or less means no room, so the result is 0 (it is not
    treated as an unbounded queue).
    """
    if cap <= 0:
        return 0
    q: queue.Queue[int] = queue.Queue(maxsize=cap)
    count = 0
    for x in xs:
        try:
            q.put_nowait(x)
        except queue.Full:
            break
        count += 1
    return count


def test_more_items_than_capacity() -> None:
    assert accepted(3, [10, 20, 30, 40, 50]) == 3


def test_fewer_items_than_capacity() -> None:
    assert accepted(5, [1, 2]) == 2


def test_exact_fit() -> None:
    assert accepted(4, [1, 2, 3, 4]) == 4


def test_empty_input() -> None:
    assert accepted(3, []) == 0


def test_zero_capacity() -> None:
    assert accepted(0, [1, 2, 3]) == 0


def test_negative_capacity() -> None:
    assert accepted(-2, [1, 2, 3]) == 0


def test_capacity_one() -> None:
    assert accepted(1, [7, 8, 9]) == 1


def test_duplicates_count_individually() -> None:
    assert accepted(3, [5, 5, 5, 5]) == 3


@pytest.mark.parametrize(
    ("cap", "n", "expected"),
    [(1, 10, 1), (10, 10, 10), (10, 3, 3), (100, 1000, 100)],
)
def test_parametrized(cap: int, n: int, expected: int) -> None:
    assert accepted(cap, list(range(n))) == expected


def test_does_not_mutate_input() -> None:
    xs = [1, 2, 3, 4]
    accepted(2, xs)
    assert xs == [1, 2, 3, 4]


def test_does_not_block() -> None:
    # A blocking put on a full queue would hang; reaching the assert means it did not.
    assert accepted(2, list(range(50))) == 2
    assert queue.Queue(maxsize=1).maxsize == 1
